    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT booking_policies_version_check CHECK ((version > 0))
);


--
-- Name: booking_policies_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.booking_policies ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.booking_policies_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: booking_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.booking_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text DEFAULT 'whatsapp'::text NOT NULL,
    provider_message_id text NOT NULL,
    sender_phone text NOT NULL,
    raw_message text NOT NULL,
    status text DEFAULT 'received'::text NOT NULL,
    parsed_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    response_text text,
    booking_id uuid,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_error_code text,
    last_error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT booking_requests_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT booking_requests_status_check CHECK ((status = ANY (ARRAY['received'::text, 'processing'::text, 'needs_clarification'::text, 'checking'::text, 'held'::text, 'confirmed'::text, 'retry_pending'::text, 'completed'::text, 'failed'::text, 'dlq_pending'::text])))
);


--
-- Name: bookings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bookings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    booking_code text NOT NULL,
    court_id uuid NOT NULL,
    sender_phone text NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    status text DEFAULT 'held'::text NOT NULL,
    hold_expires_at timestamp with time zone,
    idempotency_key text NOT NULL,
    price_total numeric(10,2) NOT NULL,
    currency text DEFAULT 'MAD'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT bookings_check CHECK ((ends_at > starts_at)),
    CONSTRAINT bookings_check1 CHECK (((status <> 'held'::text) OR (hold_expires_at IS NOT NULL))),
    CONSTRAINT bookings_price_total_check CHECK ((price_total >= (0)::numeric)),
    CONSTRAINT bookings_status_check CHECK ((status = ANY (ARRAY['held'::text, 'confirmed'::text, 'cancelled'::text, 'expired'::text])))
);


--
-- Name: conversation_state; Type: TABLE; Schema: public; Owner: -
